h=h.replace('<span class="lab">Bild / Startframe</span>','<span class="lab">Video-Prompt (10 s)</span>')
h=h.replace('<div class="meta"><span>Anhängen:</span>${c.attach.split(\',\').map(a=>`<span class="chip">@${esc(a.trim())}</span>`).join(\'\')}</div>','<div class="meta"><span class="chip">${esc(c.attach)}</span></div>')
